import React from 'react';
import './Servicios.css';

const AsesoriaContable = () => (
  <div className="servicios-container">
    <h2 className="servicios-title">Asesoría Contable</h2>
    <p>Soluciones integrales en contabilidad, organización de libros, estados financieros y cumplimiento de obligaciones legales para tu empresa o negocio.</p>
  </div>
);

export default AsesoriaContable;
